#include <iostream>
#include <string>
#include <sstream>
#include <algorithm>

int main() {
    int n;
    std::cin >> n;
    std::string s;
    std::cin >> s;

    // Replace all underscores with spaces
    for (char &ch : s) {
        if (ch == '_') {
            ch = ' ';
        }
    }

    // Insert spaces around parentheses
    std::string processed;
    for (char ch : s) {
        if (ch == '(') {
            processed += " ( ";
        } else if (ch == ')') {
            processed += " ) ";
        } else {
            processed += ch;
        }
    }

    // Split the string into parts based on whitespace
    std::istringstream iss(processed);
    std::string part;
    bool inside = false;
    int maxLength = 0, count = 0;

    while (iss >> part) {
        if (part.find('(') != std::string::npos) {
            inside = true;
        } else if (part.find(')') != std::string::npos) {
            inside = false;
        } else if (part.find('(') == std::string::npos && part.find(')') == std::string::npos) {
            if (inside) {
                count++;
            } else {
                maxLength = std::max(static_cast<int>(part.length()), maxLength);
            }
        }
    }

    std::cout << maxLength << " " << count << std::endl;
    return 0;
}
